-- Fashion demo catalog (mock data for development and demonstration).
-- Brand names are used as text only: no logos or brand imagery. Products, prices and stock are
-- invented and not affiliated with or endorsed by the brands. Generated; do not edit by hand.
-- Kept in db/seed so a deployment can start empty (FLYWAY_LOCATIONS=classpath:db/migration).

-- 1. Retire the previous demo catalog without touching users, orders or saved bundles ----------
DELETE FROM compatibility_rules;
UPDATE goal_templates SET active = FALSE;
-- products that were never ordered or used in a bundle can go; the rest are archived (order history)
DELETE FROM products p WHERE NOT EXISTS (SELECT 1 FROM order_items oi WHERE oi.product_id = p.id)
    AND NOT EXISTS (SELECT 1 FROM bundle_items bi WHERE bi.product_id = p.id);
UPDATE products SET status = 'INACTIVE', featured = FALSE, trending = FALSE, new_arrival = FALSE;
UPDATE categories SET active = FALSE;
DELETE FROM brands b WHERE NOT EXISTS (SELECT 1 FROM products p WHERE p.brand_id = b.id);
UPDATE brands SET active = FALSE;

