INSERT INTO product_variants (product_id, sku, size, color, color_hex, color_family, sort_order)
SELECT p.id, s.sku, s.size, s.color, s.color_hex, s.color_family, s.sort_order
FROM seed_variants s JOIN products p ON p.sku = s.product_sku;
INSERT INTO variant_stock (variant_id, quantity_on_hand)
SELECT v.id, s.stock FROM seed_variants s JOIN product_variants v ON v.sku = s.sku;

